<template>
  <div class="app-page" v-loading="loading">
    <div class="app-page-head"><div><h1>断言配置</h1><p>{{ item?.title || '为接口用例配置可读、可维护的结构化校验规则' }}</p></div><div><el-button @click="$router.back()">取消</el-button><el-button type="primary" :disabled="!item" @click="save">保存断言</el-button></div></div>
    <el-alert v-if="!caseId" title="请从用例库选择一条用例后进入断言配置" type="info" show-icon :closable="false" />
    <div v-else class="assert-grid">
      <el-card shadow="never"><template #header><div class="card-head"><b>断言规则</b><el-button type="primary" link @click="addRule">+ 添加规则</el-button></div></template>
        <div v-for="(rule,index) in rules" :key="index" class="rule-row"><el-select v-model="rule.source" style="width:120px"><el-option label="响应状态" value="status"/><el-option label="响应正文" value="body"/><el-option label="响应头" value="header"/><el-option label="响应时间" value="elapsed"/></el-select><el-input v-if="rule.source==='body'||rule.source==='header'" v-model="rule.path" placeholder="JSONPath / Header 名称" /><el-select v-model="rule.operator" style="width:130px"><el-option label="等于" value="eq"/><el-option label="包含" value="contains"/><el-option label="存在" value="exists"/><el-option label="小于" value="lt"/><el-option label="大于" value="gt"/></el-select><el-input v-model="rule.expected" placeholder="期望值"/><el-button text type="danger" aria-label="删除断言" @click="rules.splice(index,1)"><el-icon><Delete /></el-icon></el-button></div><el-empty v-if="rules.length===0" description="暂无断言，点击添加规则" :image-size="60" />
      </el-card>
      <el-card shadow="never"><template #header><div class="card-head"><b>最近响应样本</b><el-button :disabled="!item?.endpoint_id" :loading="sampling" @click="sample">获取最近响应</el-button></div></template><template v-if="response"><el-descriptions :column="2" border><el-descriptions-item label="状态码">{{ response.status_code }}</el-descriptions-item><el-descriptions-item label="耗时">{{ response.elapsed_ms }} ms</el-descriptions-item><el-descriptions-item label="采集时间" :span="2">{{ response.captured_at }}</el-descriptions-item></el-descriptions><pre>{{ pretty(response.body) }}</pre></template><el-empty v-else description="执行过该接口后，可在这里载入真实响应并生成断言" /></el-card>
    </div>
  </div>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { Delete } from '@element-plus/icons-vue';import { ElMessage } from 'element-plus';import { caseApi,endpointRuntimeApi } from '@/api'
const route=useRoute(),caseId=String(route.params.id||route.query.case_id||'');const item=ref<any>(null),loading=ref(false),sampling=ref(false),response=ref<any>(null),rules=ref<any[]>([])
function addRule(){rules.value.push({source:'body',path:'$.data',operator:'exists',expected:''})}function pretty(v:any){return JSON.stringify(v,null,2)}
async function load(){if(!caseId)return;loading.value=true;try{const r:any=await caseApi.get(caseId);item.value=r?.data;const expected=item.value?.expected_result||{};rules.value=(expected.assertions||[]).map((x:any)=>({...x,expected:String(x.expected??'')}));if(expected.status_code&&!rules.value.some(x=>x.source==='status'))rules.value.unshift({source:'status',path:'',operator:'eq',expected:String(expected.status_code)})}finally{loading.value=false}}
async function sample(){sampling.value=true;try{const r:any=await endpointRuntimeApi.lastResponse(item.value.endpoint_id);response.value=r?.data;if(!response.value)ElMessage.info('该接口暂无执行响应')}finally{sampling.value=false}}
async function save(){const normalized=rules.value.map(r=>({...r,expected:r.operator==='exists'?true:r.expected}));const status=normalized.find(r=>r.source==='status'&&r.operator==='eq');await caseApi.update(caseId,{expected_result:{status_code:status?Number(status.expected):undefined,assertions:normalized}});ElMessage.success('断言已保存')}onMounted(load)
</script>
<style scoped>.app-page-head,.card-head{display:flex;justify-content:space-between;align-items:flex-start}.app-page-head h1{margin:0 0 6px;font-size:22px}.app-page-head p{margin:0;color:var(--app-text-secondary)}.assert-grid{display:grid;grid-template-columns:minmax(0,3fr) minmax(320px,2fr);gap:14px;margin-top:18px}.rule-row{display:flex;gap:8px;margin-bottom:10px}.rule-row .el-input{min-width:120px}.card-head{align-items:center}pre{max-height:430px;overflow:auto;background:#0f172a;color:#dbeafe;border-radius:7px;padding:14px;font-size:12px}@media(max-width:960px){.assert-grid{grid-template-columns:1fr}.rule-row{flex-wrap:wrap}.rule-row .el-input{flex:1}}</style>
